const uint8_t* harryMem(uint32_t va) {
    for (const Blob& b : kBlobs) if (va >= b.va && va < b.va + b.len) return b.p + (va - b.va);
    return nullptr;
}

uint32_t harryMemAddr(const uint8_t* p) {
    for (const Blob& b : kBlobs) if (p >= b.p && p < b.p + b.len) return b.va + uint32_t(p - b.p);
    return 0;
}

